import{z as o,x as B,o as l,c as p,q as r,j as i,D as E,d as s,s as A,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"高层次综合 HLS","description":"","frontmatter":{"title":"高层次综合 HLS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hls.md","filePath":"cs/hls.md","lastUpdated":1791063341000}'),d={name:"cs/hls.md"};function h(D,a,L,S,m,C){const t=B("Mermaid");return l(),p("div",null,[a[2]||(a[2]=r('<h1 id="高层次综合-hls" tabindex="-1">高层次综合 HLS <a class="header-anchor" href="#高层次综合-hls" aria-label="Permalink to &quot;高层次综合 HLS&quot;">​</a></h1><div class="epigraph"><p>从 C/C++ 的循环生成流水线 RTL：调度决定哪一拍做乘，绑定决定用几份 DSP；程序员写的仍是算法，工具补时序状态机。</p><footer>—— 据 Coussy and Morawiec, High-Level Synthesis；Gajski et al., High-Level Synthesis 整理</footer></div><p><a href="/cs/fpga-place-route">上一课</a>把手工 RTL 送到 P&amp;R。算术单元里的<a href="/cs/wallace-carry-save">华莱士</a>与<a href="/cs/fixed-point-dsp">定点 MAC</a> 用 C 写往往更短。缺口是 <strong>HLS</strong>：把高级语言调度成 RTL，再走同一套综合与布局，而不是在 FPGA 上跑 CPU 解释 C。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RTL 要显写流水线级与握手。<a href="/cs/verilog-basics">Verilog 基本</a>已警告不要把 HDL 当软件。HLS 反向：接受「软件式」循环，用约束（目标周期、II、数组到 RAM/LUT 的绑定）推出状态机与数据通路。缺口不是新的乘法器电路，而是<strong>调度与绑定</strong>这两步。</p><p>II（initiation interval）=1 意味着每拍启动下一次循环迭代，需要足够的 DSP 与内存端口。这与组成课流水线是同一思想，工具自动插寄存器。</p><p><span class="marginnote">数字实例：循环体里有 2 次乘法，II=1 就要一拍内挤进 2 个乘法器、占 2 块 DSP；若板上只剩 1 块，工具只好把 II 提到 2，吞吐立刻减半——资源与性能是同一张表的两侧。</span></p><p><span class="marginnote">术语翻译：II（initiation interval，启动间隔）就是「隔几拍才能启动下一次循环迭代」。II=1 像流水线每拍落一件产品，II=4 则四拍才落一件；HLS 调度器的主要工作之一就是把这个数压下去。</span></p><h3 id="hls-不是「保证比手写-rtl-更快」" tabindex="-1">HLS 不是「保证比手写 RTL 更快」 <a class="header-anchor" href="#hls-不是「保证比手写-rtl-更快」" aria-label="Permalink to &quot;HLS 不是「保证比手写 RTL 更快」&quot;">​</a></h3><p>质量取决于可综合子集、依赖分析、是否把数组分区。随意指针与系统调用无法变电路。把 HLS 当成在 PL 里跑 Linux 用户程序，会与软核 CPU 方案混层。</p><p><span class="marginnote">Gajski 等人定义 HLS 的调度/绑定/分配。现代工具（Vitis HLS 等）实现不同，本课钉共同步骤。本栏不把 HLS 写成大模型算子生成器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入：C 函数 + 接口 pragma（AXI 流、寄存器）。分析循环携带依赖。调度：在周期约束下安排运算。绑定：运算映射到 FPGA DSP 或 ASIC 乘法器。输出：RTL，然后<a href="/cs/synthesis-netlist">综合</a>与 P&amp;R。验证：C 仿真 vs RTL 协同仿真——后课测试平台家族。</p>',13)),(l(),i(n,null,{default:E(()=>[A(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22C%20%E5%BE%AA%E7%8E%AF%20%2B%20%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20SCH%5B%22%E8%B0%83%E5%BA%A6%E4%B8%8E%E7%BB%91%E5%AE%9A%22%5D%0A%20%20SCH%20--%3E%20RTL%5B%22%E7%94%9F%E6%88%90%20RTL%22%5D%0A%20%20RTL%20--%3E%20PNR%5B%22%E5%90%8C%E4%B8%80%E5%A5%97%E7%BB%BC%E5%90%88%E4%B8%8E%20P%26R%22%5D%0A%20%20PNR%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AASIC%20%E6%A0%87%E5%87%86%E5%8D%95%E5%85%83%E5%8F%A6%E4%B8%80%E6%9D%A1%E8%B7%AF%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[s("定点类型在 HLS 里常显式标注位宽，对应定点 DSP 课的 Q 格式，而不是偷偷用 "),e("code",null,"float"),s(" 然后抱怨资源。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"后课 ASIC 流程也可以 HLS 到标准单元，只是库不同。手写 RTL 仍适合控制密集与极限时序（异步 FIFO 指针）。HLS 适合规则循环的算术阵列。验证负担不消失：生成 RTL 仍要 STA 与功能测试。",-1)),a[6]||(a[6]=e("p",null,"II=1 到底能不能达成，卡在哪一步：",-1)),(l(),i(n,null,{default:E(()=>[A(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E7%9B%AE%E6%A0%87%3A%20II%20%3D%201%22%5D%20--%3E%20D%7B%22%E5%BE%AA%E7%8E%AF%E6%90%BA%E5%B8%A6%E4%BE%9D%E8%B5%96%3F%22%7D%0A%20%20D%20--%20%22%E6%9C%89%22%20--%3E%20W%5B%22%E8%BF%AD%E4%BB%A3%E8%A2%AB%E4%BE%9D%E8%B5%96%E5%8D%A1%E4%BD%8F%2C%20II%20%E5%8D%87%E9%AB%98%22%5D%0A%20%20D%20--%20%22%E6%97%A0%22%20--%3E%20R%7B%22%E5%86%85%E5%AD%98%E7%AB%AF%E5%8F%A3%E5%A4%9F%E5%B9%B6%E8%A1%8C%E8%AE%BF%E5%AD%98%3F%22%7D%0A%20%20R%20--%20%22%E4%B8%8D%E5%A4%9F%22%20--%3E%20P%5B%22%E6%95%B0%E7%BB%84%E5%88%86%E5%8C%BA%2F%E5%A4%8D%E5%88%B6%E5%88%B0%E5%A4%9A%E5%9D%97%20RAM%22%5D%0A%20%20R%20--%20%22%E5%A4%9F%22%20--%3E%20B%5B%22%E8%BF%90%E7%AE%97%E7%BB%91%E5%AE%9A%E5%88%B0%20DSP%22%5D%0A%20%20P%20--%3E%20B%0A%20%20B%20--%3E%20O%5B%22%E6%AF%8F%E6%8B%8D%E5%90%AF%E5%8A%A8%E4%B8%80%E6%AC%A1%E8%BF%AD%E4%BB%A3%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">常见误区：把 HLS 当「C 编译器加速版」。指针别名、动态 malloc、系统调用都变不成电路，工具要么报错、要么悄悄生成慢速兜底；主动分区数组、写清位宽与接口 pragma，生成质量才上得来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不教某 pragma 清单，不把 PyTorch 图到 FPGA 的工具链写进主干（那会滑向大模型栏）。不声称 HLS 取代 CDC 设计：跨时钟仍要 FIFO 或工具认的同步器原语。</p><p>后课默认：HLS 产出仍是 RTL，走同一时序闭合；调度/绑定是新增的自动层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>C 循环经调度与绑定变成流水线 RTL。</li><li>仍要综合、STA、P&amp;R；不是在 LUT 上解释 C。</li><li>不规则控制与 CDC 仍宜手写。</li><li>出处：Coussy and Morawiec；Gajski et al., <em>High-Level Synthesis</em>。</li></ul>',6))])}const P=o(d,[["render",h]]);export{c as __pageData,P as default};
